import sys
import json
from functools import cmp_to_key

def solve():
    data = json.loads(sys.stdin.readline())
    K = data['K']
    villages = data['villages']
    n = len(villages)

    xs = [v[0] for v in villages]
    ys = [v[1] for v in villages]

    # 预计算平方距离
    dist2 = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dx = xs[i] - xs[j]
            dy = ys[i] - ys[j]
            d2 = dx * dx + dy * dy
            dist2[i][j] = dist2[j][i] = d2

    # 初始簇：每个点自成一簇
    clusters = [[i] for i in range(n)]

    EPS = 1e-9               # 用于判断平方距离相等
    while len(clusters) > K:
        m = len(clusters)
        best_d2 = float('inf')
        best_i = best_j = -1
        best_key = (0, 0)

        for i in range(m):
            for j in range(i + 1, m):
                A = clusters[i]
                B = clusters[j]
                # 簇间最小平方距离
                min_d2 = float('inf')
                for a in A:
                    for b in B:
                        d2 = dist2[a][b]
                        if d2 < min_d2:
                            min_d2 = d2

                min_a, min_b = A[0], B[0]   # 簇内已有序，首元素即最小编号
                if min_a > min_b:
                    min_a, min_b = min_b, min_a
                key = (min_a, min_b)

                if min_d2 < best_d2 - EPS:
                    best_d2 = min_d2
                    best_i, best_j = i, j
                    best_key = key
                elif abs(min_d2 - best_d2) <= EPS and key < best_key:
                    best_i, best_j = i, j
                    best_key = key

        # 合并两个簇，保持点编号有序
        merged = sorted(clusters[best_i] + clusters[best_j])
        if best_i < best_j:
            clusters.pop(best_j)
            clusters.pop(best_i)
        else:
            clusters.pop(best_i)
            clusters.pop(best_j)
        clusters.append(merged)

    # 计算中心及排序
    infos = []
    for cl in clusters:
        sx = sum(xs[i] for i in cl) / len(cl)
        sy = sum(ys[i] for i in cl) / len(cl)
        infos.append((sx, sy, cl[0], cl))   # (中心x, 中心y, 最小编号, 点列表)

    SORT_EPS = 1e-12
    def cmp(a, b):
        if abs(a[0] - b[0]) >= SORT_EPS:
            return -1 if a[0] < b[0] else 1
        if abs(a[1] - b[1]) >= SORT_EPS:
            return -1 if a[1] < b[1] else 1
        return -1 if a[2] < b[2] else 1

    infos.sort(key=cmp_to_key(cmp))

    # 分配最终编号
    ans = [0] * n
    for label, info in enumerate(infos):
        for idx in info[3]:
            ans[idx] = label

    print(json.dumps(ans))


if __name__ == '__main__':
    solve()
```

