import sys
import json

def solve():
    line = sys.stdin.readline().strip()
    data = json.loads(line)
    K = data['K']
    villages = data['villages']
    n = len(villages)
    # 预计算平方距离矩阵
    dist2 = [[0.0]*n for _ in range(n)]
    xs = [p[0] for p in villages]
    ys = [p[1] for p in villages]
    for i in range(n):
        for j in range(i+1, n):
            dx = xs[i] - xs[j]
            dy = ys[i] - ys[j]
            d2 = dx*dx + dy*dy
            dist2[i][j] = d2
            dist2[j][i] = d2

    # 初始簇
    clusters = [[i] for i in range(n)]

    while len(clusters) > K:
        m = len(clusters)
        best_d2 = float('inf')
        best_key = (0,0)
        best_i = best_j = -1
        for i in range(m):
            for j in range(i+1, m):
                A = clusters[i]
                B = clusters[j]
                # 计算簇间最小平方距离
                min_d2 = float('inf')
                for a in A:
                    for b in B:
                        d2 = dist2[a][b]
                        if d2 < min_d2:
                            min_d2 = d2
                # 平局关键字：最小编号，有序对
                min_a = A[0]  # 因为有序，第一个就是最小编号
                min_b = B[0]
                if min_a < min_b:
                    key = (min_a, min_b)
                else:
                    key = (min_b, min_a)
                if min_d2 < best_d2 - 1e-12:  # 由于是平方距离，需要EPS？浮点比较，直接相等比较时，因为平方距离可能不是整数，我们是浮点数，可能会有精度问题。原题解用EPS。我们可以用if min_d2 < best_d2: 无需EPS，直接比较。但如果有两个不同的簇对平方距离非常接近，可能导致浮点误差。为了安全，使用EPS。使用1e-12可能太小，因为距离平方可达1e12。使用相对或绝对？使用1e-9。干脆直接用<比较，但为了处理平局（相等），用abs(min_d2 - best_d2) < 1e-9作为相等。我们采用和原题解类似：if min_d2 < best_d2 - 1e-9: 更新；else if abs(min_d2 - best_d2) <= 1e-9 and key < best_key: 更新。但初始best_d2为inf，不会相等。这样。
                if min_d2 < best_d2 - 1e-9:
                    best_d2 = min_d2
                    best_key = key
                    best_i, best_j = i, j
                elif abs(min_d2 - best_d2) <= 1e-9:
                    if key < best_key:
                        best_key = key
                        best_i, best_j = i, j
        # 合并
        new_cluster = sorted(clusters[best_i] + clusters[best_j])
        # 删除 j 和 i，注意顺序：先删除大的索引
        if best_i < best_j:
            clusters.pop(best_j)
            clusters.pop(best_i)
        else:
            clusters.pop(best_i)
            clusters.pop(best_j)
        clusters.append(new_cluster)

    # 现在有K个簇，计算中心和排序
    infos = []
    for cluster in clusters:
        sum_x = 0.0
        sum_y = 0.0
        for idx in cluster:
            sum_x += xs[idx]
            sum_y += ys[idx]
        cx = sum_x / len(cluster)
        cy = sum_y / len(cluster)
        infos.append((cx, cy, cluster[0], cluster))  # (cx, cy, min_id, cluster)

    # 排序
    EPS = 1e-12
    def cluster_less(a, b):
        if abs(a[0] - b[0]) >= EPS:
            return a[0] < b[0]
        if abs(a[1] - b[1]) >= EPS:
            return a[1] < b[1]
        return a[2] < b[2]

    from functools import cmp_to_key
    infos.sort(key=cmp_to_key(lambda x,y: -1 if cluster_less(x,y) else (1 if cluster_less(y,x) else 0)))

    # 也可以用sorted自定义cmp，或者用排序的key生成元组（用round），但这里直接用比较函数。
    # 分配编号
    ans = [0] * n
    for label, info in enumerate(infos):
        for idx in info[3]:
            ans[idx] = label
    print(json.dumps(ans))

if __name__ == '__main__':
    solve()
