```java
import java.util.*;
import java.util.regex.*;

public class Main {
    static double EPS = 1e-9; // 平方距离比较时用
    static double EPS_SORT = 1e-12;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine().trim();
        // 提取所有数字
        Pattern pattern = Pattern.compile("-?\\d+(\\.\\d+)?");
        Matcher matcher = pattern.matcher(line);
        List<String> numbers = new ArrayList<>();
        while (matcher.find()) {
            numbers.add(matcher.group());
        }
        int K = Integer.parseInt(numbers.get(0));
        int n = (numbers.size() - 1) / 2;
        double[] xs = new double[n];
        double[] ys = new double[n];
        for (int i = 0; i < n; i++) {
            xs[i] = Double.parseDouble(numbers.get(1 + 2 * i));
            ys[i] = Double.parseDouble(numbers.get(1 + 2 * i + 1));
        }

        double[][] dist2 = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double dx = xs[i] - xs[j];
                double dy = ys[i] - ys[j];
                double d2 = dx * dx + dy * dy;
                dist2[i][j] = d2;
                dist2[j][i] = d2;
            }
        }

        List<List<Integer>> clusters = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> cl = new ArrayList<>();
            cl.add(i);
            clusters.add(cl);
        }

        while (clusters.size() > K) {
            int m = clusters.size();
            double bestD2 = Double.POSITIVE_INFINITY;
            int bestI = -1, bestJ = -1;
            long bestKeySmall = -1, bestKeyLarge = -1; // 用encoded表示key
            for (int i = 0; i < m; i++) {
                for (int j = i + 1; j < m; j++) {
                    List<Integer> A = clusters.get(i);
                    List<Integer> B = clusters.get(j);
                    double minD2 = Double.POSITIVE_INFINITY;
                    for (int a : A) {
                        for (int b : B) {
                            double d2 = dist2[a][b];
                            if (d2 < minD2) {
                                minD2 = d2;
                            }
                        }
                    }
                    int minA = A.get(0);
                    int minB = B.get(0);
                    if (minA > minB) {
                        int tmp = minA; minA = minB; minB = tmp;
                    }
                    // 比较
                    if (minD2 < bestD2 - EPS) {
                        bestD2 = minD2;
                        bestI = i; bestJ = j;
                        bestKeySmall = minA; bestKeyLarge = minB;
                    } else if (Math.abs(minD2 - bestD2) <= EPS) {
                        // 比较key
                        if (minA < bestKeySmall || (minA == bestKeySmall && minB < bestKeyLarge)) {
                            bestI = i; bestJ = j;
                            bestKeySmall = minA; bestKeyLarge = minB;
                        }
                    }
                }
            }
            // 合并
            List<Integer> merged = new ArrayList<>();
            merged.addAll(clusters.get(bestI));
            merged.addAll(clusters.get(bestJ));
            Collections.sort(merged);
            if (bestI < bestJ) {
                clusters.remove(bestJ);
                clusters.remove(bestI);
            } else {
                clusters.remove(bestI);
                clusters.remove(bestJ);
            }
            clusters.add(merged);
        }

        // 计算中心
        int nClusters = clusters.size();
        double[] centerX = new double[nClusters];
        double[] centerY = new double[nClusters];
        int[] minId = new int[nClusters];
        for (int i = 0; i < nClusters; i++) {
            List<Integer> cl = clusters.get(i);
            double sumX = 0, sumY = 0;
            for (int idx : cl) {
                sumX += xs[idx];
                sumY += ys[idx];
            }
            centerX[i] = sumX / cl.size();
            centerY[i] = sumY / cl.size();
            minId[i] = cl.get(0);
        }

        // 排序索引
        Integer[] order = new Integer[nClusters];
        for (int i = 0; i < nClusters; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> {
            if (Math.abs(centerX[a] - centerX[b]) >= EPS_SORT) {
                return Double.compare(centerX[a], centerX[b]);
            }
            if (Math.abs(centerY[a] - centerY[b]) >= EPS_SORT) {
                return Double.compare(centerY[a], centerY[b]);
            }
            return Integer.compare(minId[a], minId[b]);
        });

        // 分配编号
        int[] ans = new int[n];
        for (int newLabel = 0; newLabel < nClusters; newLabel++) {
            int origIndex = order[newLabel];
            for (int idx : clusters.get(origIndex)) {
                ans[idx] = newLabel;
            }
        }

        // 输出JSON数组
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(", ");
            sb.append(ans[i]);
        }
        sb.append("]");
        System.out.println(sb.toString());
    }
}
