C++代码：使用正则，C++11有<regex>。解析输入字符串。然后同样逻辑。用vector存储。距离平方。簇用vector<vector<int>>。合并后排序。最后排序用自定义比较。输出JSON数组，带空格。注意精度，使用double。

C++代码：

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <regex>
#include <cmath>
#include <algorithm>
#include <limits>

using namespace std;

const double EPS = 1e-9;
const double EPS_SORT = 1e-12;

int main() {
    string line;
    getline(cin, line);
    // 提取所有数字
    regex num_re("-?\\d+(\\.\\d+)?");
    sregex_iterator iter(line.begin(), line.end(), num_re);
    sregex_iterator end;
    vector<string> numbers;
    while (iter != end) {
        numbers.push_back(iter->str());
        ++iter;
    }
    int K = stoi(numbers[0]);
    int n = (numbers.size() - 1) / 2;
    vector<double> xs(n), ys(n);
    for (int i = 0; i < n; i++) {
        xs[i] = stod(numbers[1 + 2*i]);
        ys[i] = stod(numbers[1 + 2*i + 1]);
    }

    // 距离平方矩阵
    vector<vector<double>> dist2(n, vector<double>(n, 0.0));
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            double dx = xs[i] - xs[j];
            double dy = ys[i] - ys[j];
            double d2 = dx*dx + dy*dy;
            dist2[i][j] = dist2[j][i] = d2;
        }
    }

    // 初始化簇
    vector<vector<int>> clusters(n);
    for (int i = 0; i < n; i++) clusters[i].push_back(i);

    while (clusters.size() > K) {
        int m = clusters.size();
        double bestD2 = numeric_limits<double>::infinity();
        int bestI = -1, bestJ = -1;
        int bestKeySmall = -1, bestKeyLarge = -1;
        for (int i = 0; i < m; i++) {
            for (int j = i+1; j < m; j++) {
                const auto& A = clusters[i];
                const auto& B = clusters[j];
                double minD2 = numeric_limits<double>::infinity();
                for (int a : A) {
                    for (int b : B) {
                        double d2 = dist2[a][b];
                        if (d2 < minD2) minD2 = d2;
                    }
                }
                int minA = A[0]; // 已排序
                int minB = B[0];
                if (minA > minB) swap(minA, minB);
                // 更新最优
                if (minD2 < bestD2 - EPS) {
                    bestD2 = minD2;
                    bestI = i; bestJ = j;
                    bestKeySmall = minA; bestKeyLarge = minB;
                } else if (fabs(minD2 - bestD2) <= EPS) {
                    if (minA < bestKeySmall || (minA == bestKeySmall && minB < bestKeyLarge)) {
                        bestI = i; bestJ = j;
                        bestKeySmall = minA; bestKeyLarge = minB;
                    }
                }
            }
        }
        // 合并
        vector<int> merged = clusters[bestI];
        merged.insert(merged.end(), clusters[bestJ].begin(), clusters[bestJ].end());
        sort(merged.begin(), merged.end());
        if (bestI < bestJ) {
            clusters.erase(clusters.begin() + bestJ);
            clusters.erase(clusters.begin() + bestI);
        } else {
            clusters.erase(clusters.begin() + bestI);
            clusters.erase(clusters.begin() + bestJ);
        }
        clusters.push_back(moved(merged)); // 或直接clusters.push_back(merged);
    }

    int nClusters = clusters.size();
    vector<double> centerX(nClusters), centerY(nClusters);
    vector<int> minId(nClusters);
    for (int i = 0; i < nClusters; i++) {
        double sumX = 0, sumY = 0;
        for (int idx : clusters[i]) {
            sumX += xs[idx];
            sumY += ys[idx];
        }
        centerX[i] = sumX / clusters[i].size();
        centerY[i] = sumY / clusters[i].size();
        minId[i] = clusters[i][0];
    }

    // 排序索引
    vector<int> order(nClusters);
    for (int i = 0; i < nClusters; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (fabs(centerX[a] - centerX[b]) >= EPS_SORT)
            return centerX[a] < centerX[b];
        if (fabs(centerY[a] - centerY[b]) >= EPS_SORT)
            return centerY[a] < centerY[b];
        return minId[a] < minId[b];
    });

    // 生成答案
    vector<int> ans(n);
    for (int newLabel = 0; newLabel < nClusters; newLabel++) {
        int orig = order[newLabel];
        for (int idx : clusters[orig]) {
            ans[idx] = newLabel;
        }
    }

    // 输出JSON
    cout << "[";
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << ", ";
        cout << ans[i];
    }
    cout << "]" << endl;

    return 0;
}
```

